import { sql } from "drizzle-orm";
import {
  check,
  integer,
  sqliteTable,
  text,
  type AnySQLiteColumn,
} from "drizzle-orm/sqlite-core";

export const lawyers = sqliteTable(
  "lawyers",
  {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    title: text("title").notNull(),
  },
  (table) => [
    check("lawyers_name_non_empty", sql`length(trim(${table.name})) > 0`),
    check("lawyers_title_non_empty", sql`length(trim(${table.title})) > 0`),
  ],
);

export const documents = sqliteTable(
  "documents",
  {
    id: text("id").primaryKey(),
    title: text("title").notNull(),
    type: text("type").notNull(),
    pages: integer("pages").notNull(),
    uploadedAt: text("uploaded_at").notNull(),
    uploadedByLawyerId: text("uploaded_by_lawyer_id")
      .notNull()
      .references(() => lawyers.id),
    supersedesDocumentId: text("supersedes_document_id").references(
      (): AnySQLiteColumn => documents.id,
    ),
  },
  (table) => [
    check("documents_title_non_empty", sql`length(trim(${table.title})) > 0`),
    check("documents_type_non_empty", sql`length(trim(${table.type})) > 0`),
    check(
      "documents_pages_positive_integer",
      sql`typeof(${table.pages}) = 'integer' and ${table.pages} > 0`,
    ),
    check(
      "documents_uploaded_at_iso_8601_utc",
      sql`
        substr(${table.uploadedAt}, 1, 19) glob '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]'
        and unixepoch(${table.uploadedAt}) is not null
        and strftime('%Y-%m-%dT%H:%M:%S', unixepoch(${table.uploadedAt}), 'unixepoch') = substr(${table.uploadedAt}, 1, 19)
        and (
          (length(${table.uploadedAt}) = 20 and substr(${table.uploadedAt}, 20, 1) = 'Z')
          or (
            length(${table.uploadedAt}) > 21
            and substr(${table.uploadedAt}, 20, 1) = '.'
            and substr(${table.uploadedAt}, -1, 1) = 'Z'
            and substr(${table.uploadedAt}, 21, length(${table.uploadedAt}) - 21) not glob '*[^0-9]*'
          )
        )
      `,
    ),
  ],
);

import Database from "better-sqlite3";
import { mkdirSync } from "node:fs";
import path from "node:path";

export const DEFAULT_DATABASE_PATH = "data/lexroom.db";

export function resolveDatabasePath(databaseUrl = process.env.DATABASE_URL): string {
  return path.resolve(databaseUrl || DEFAULT_DATABASE_PATH);
}

export function openDatabase(
  databasePath: string,
  options: { create?: boolean } = {},
): Database.Database {
  const resolvedPath = path.resolve(databasePath);
  if (options.create) {
    mkdirSync(path.dirname(resolvedPath), { recursive: true });
  }

  const sqlite = new Database(resolvedPath, {
    fileMustExist: !options.create,
  });
  sqlite.pragma("foreign_keys = ON");
  return sqlite;
}

import { drizzle } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import path from "node:path";

import documentFixtures from "../../../samples/documents.json";
import lawyerFixtures from "../../../samples/lawyers.json";
import { openDatabase, resolveDatabasePath } from "./database";

type PublicLawyer = {
  id: string;
  name: string;
  title: string;
};

type PublicDocument = {
  id: string;
  title: string;
  type: string;
  pages: number;
  uploadedAt: string;
  uploadedByLawyerId: string;
  supersedesDocumentId: string | null;
};

const lawyers: PublicLawyer[] = lawyerFixtures.map((lawyer) => ({
  id: lawyer.id,
  name: lawyer.name,
  title: lawyer.title,
}));

// Keep this mapping explicit: findings are private fake-AI input, not database data.
const documents: PublicDocument[] = documentFixtures.map((document) => ({
  id: document.id,
  title: document.title,
  type: document.type,
  pages: document.pages,
  uploadedAt: document.uploadedAt,
  uploadedByLawyerId: document.uploadedBy,
  supersedesDocumentId: document.supersedes,
}));

export class FixtureConflictError extends Error {
  constructor(kind: "lawyer" | "document", id: string) {
    super(
      `Sample ${kind} ${id} conflicts with existing public data; no fixture data was changed.`,
    );
    this.name = "FixtureConflictError";
  }
}

function orderDocumentsBySupersedes(
  fixtures: PublicDocument[],
): PublicDocument[] {
  const byId = new Map(fixtures.map((document) => [document.id, document]));
  const ordered: PublicDocument[] = [];
  const visited = new Set<string>();
  const visiting = new Set<string>();

  const visit = (document: PublicDocument) => {
    if (visited.has(document.id)) return;
    if (visiting.has(document.id)) {
      throw new Error(`Sample document supersedes cycle includes ${document.id}.`);
    }

    visiting.add(document.id);
    const predecessor = document.supersedesDocumentId
      ? byId.get(document.supersedesDocumentId)
      : undefined;
    if (predecessor) visit(predecessor);
    visiting.delete(document.id);
    visited.add(document.id);
    ordered.push(document);
  };

  for (const document of fixtures) visit(document);
  return ordered;
}

function sameLawyer(existing: PublicLawyer, fixture: PublicLawyer): boolean {
  return existing.name === fixture.name && existing.title === fixture.title;
}

function sameDocument(
  existing: PublicDocument,
  fixture: PublicDocument,
): boolean {
  return (
    existing.title === fixture.title &&
    existing.type === fixture.type &&
    existing.pages === fixture.pages &&
    existing.uploadedAt === fixture.uploadedAt &&
    existing.uploadedByLawyerId === fixture.uploadedByLawyerId &&
    existing.supersedesDocumentId === fixture.supersedesDocumentId
  );
}

export function setupDatabase(
  databasePath = resolveDatabasePath(),
  migrationsFolder = path.resolve(process.cwd(), "drizzle"),
): void {
  const sqlite = openDatabase(databasePath, { create: true });

  try {
    migrate(drizzle(sqlite), { migrationsFolder });

    const findLawyer = sqlite.prepare<{ id: string }, PublicLawyer>(
      "select id, name, title from lawyers where id = @id",
    );
    const insertLawyer = sqlite.prepare(
      "insert into lawyers (id, name, title) values (@id, @name, @title)",
    );
    const findDocument = sqlite.prepare<
      { id: string },
      PublicDocument
    >(`
      select
        id,
        title,
        type,
        pages,
        uploaded_at as uploadedAt,
        uploaded_by_lawyer_id as uploadedByLawyerId,
        supersedes_document_id as supersedesDocumentId
      from documents
      where id = @id
    `);
    const insertDocument = sqlite.prepare(`
      insert into documents (
        id,
        title,
        type,
        pages,
        uploaded_at,
        uploaded_by_lawyer_id,
        supersedes_document_id
      ) values (
        @id,
        @title,
        @type,
        @pages,
        @uploadedAt,
        @uploadedByLawyerId,
        @supersedesDocumentId
      )
    `);

    sqlite.transaction(() => {
      for (const lawyer of lawyers) {
        const existing = findLawyer.get({ id: lawyer.id });
        if (!existing) insertLawyer.run(lawyer);
        else if (!sameLawyer(existing, lawyer)) {
          throw new FixtureConflictError("lawyer", lawyer.id);
        }
      }

      for (const document of orderDocumentsBySupersedes(documents)) {
        const existing = findDocument.get({ id: document.id });
        if (!existing) insertDocument.run(document);
        else if (!sameDocument(existing, document)) {
          throw new FixtureConflictError("document", document.id);
        }
      }
    })();
  } finally {
    sqlite.close();
  }
}

import type Database from "better-sqlite3";

import type { WorkspaceSnapshot } from "../../shared/api";

const MONTHLY_REVIEW_LIMIT = 10;

type PersistedDocument = Omit<
  WorkspaceSnapshot["documents"][number],
  "latestReviewAttempt" | "latestSuccessfulReview"
>;

function utcMonth(now: Date): string {
  const year = now.getUTCFullYear();
  const month = String(now.getUTCMonth() + 1).padStart(2, "0");
  return `${year}-${month}`;
}

function compareUploadedAtNewestFirst(
  left: PersistedDocument,
  right: PersistedDocument,
): number {
  const leftSecond = left.uploadedAt.slice(0, 19);
  const rightSecond = right.uploadedAt.slice(0, 19);
  if (leftSecond !== rightSecond) return leftSecond < rightSecond ? 1 : -1;

  const fraction = (timestamp: string) =>
    timestamp[19] === "." ? timestamp.slice(20, -1) : "";
  const leftFraction = fraction(left.uploadedAt).replace(/0+$/, "");
  const rightFraction = fraction(right.uploadedAt).replace(/0+$/, "");
  const precision = Math.max(leftFraction.length, rightFraction.length);
  const normalizedLeft = leftFraction.padEnd(precision, "0");
  const normalizedRight = rightFraction.padEnd(precision, "0");
  if (normalizedLeft !== normalizedRight) {
    return normalizedLeft < normalizedRight ? 1 : -1;
  }

  return left.id < right.id ? -1 : left.id > right.id ? 1 : 0;
}

export function readWorkspaceSnapshot(
  sqlite: Database.Database,
  now: Date,
): WorkspaceSnapshot {
  const lawyers = sqlite
    .prepare<
      [],
      WorkspaceSnapshot["lawyers"][number]
    >("select id, name, title from lawyers order by name asc, id asc")
    .all();
  const persistedDocuments = sqlite
    .prepare<[], PersistedDocument>(`
      select
        id,
        title,
        type,
        pages,
        uploaded_at as uploadedAt,
        uploaded_by_lawyer_id as uploadedByLawyerId,
        supersedes_document_id as supersedesDocumentId
      from documents
    `)
    .all()
    .sort(compareUploadedAtNewestFirst);

  return {
    lawyers,
    documents: persistedDocuments.map((document) => ({
      ...document,
      latestReviewAttempt: null,
      latestSuccessfulReview: null,
    })),
    monthlyAllowance: {
      month: utcMonth(now),
      limit: MONTHLY_REVIEW_LIMIT,
      completed: 0,
      reserved: 0,
      available: MONTHLY_REVIEW_LIMIT,
    },
  };
}

import type Database from "better-sqlite3";
import { Hono } from "hono";

import type { ApiError } from "../shared/api";
import { openDatabase, resolveDatabasePath } from "./db/database";
import { readWorkspaceSnapshot } from "./workspace/read-workspace";

type ApiDependencies = {
  openWorkspaceDatabase: () => Database.Database;
  now: () => Date;
  logger: Pick<Console, "error">;
};

const defaultDependencies: ApiDependencies = {
  openWorkspaceDatabase: () => openDatabase(resolveDatabasePath()),
  now: () => new Date(),
  logger: console,
};

export function createApi(
  dependencies: ApiDependencies = defaultDependencies,
): Hono {
  const app = new Hono().basePath("/api");

  app.get("/health", (c) => {
    return c.json({ status: "ok" });
  });

  app.get("/workspace", (c) => {
    c.header("Cache-Control", "no-store");

    let sqlite: Database.Database | undefined;
    try {
      sqlite = dependencies.openWorkspaceDatabase();
      return c.json(readWorkspaceSnapshot(sqlite, dependencies.now()));
    } catch (error) {
      dependencies.logger.error("Failed to read the workspace snapshot", error);
      const body: ApiError = {
        error: {
          code: "WORKSPACE_UNAVAILABLE",
          message: "Workspace data is unavailable.",
        },
      };
      return c.json(body, 500);
    } finally {
      sqlite?.close();
    }
  });

  return app;
}

export const api = createApi();

export type WorkspaceSnapshot = {
  lawyers: Array<{
    id: string;
    name: string;
    title: string;
  }>;
  documents: Array<{
    id: string;
    title: string;
    type: string;
    pages: number;
    uploadedAt: string;
    uploadedByLawyerId: string;
    supersedesDocumentId: string | null;
    latestReviewAttempt: null;
    latestSuccessfulReview: null;
  }>;
  monthlyAllowance: {
    month: string;
    limit: number;
    completed: number;
    reserved: number;
    available: number;
  };
};

export type ApiError = {
  error: {
    code: string;
    message: string;
  };
};

"use client";

import {
  QueryClient,
  QueryClientProvider,
  useQuery,
  useQueryClient,
} from "@tanstack/react-query";
import { useEffect, useMemo, useState, useSyncExternalStore } from "react";

import type { WorkspaceSnapshot } from "../shared/api";
import {
  WORKSPACE_QUERY_KEY,
  WORKSPACE_QUERY_OPTIONS,
} from "./workspace-query";

export const SELECTED_LAWYER_STORAGE_KEY = "lexroom.selected-lawyer-id";

const selectionListeners = new Set<() => void>();
let inMemorySelection: string | null = null;

function readSelectedLawyerId(): string | null {
  if (typeof window === "undefined") return null;
  try {
    return window.localStorage.getItem(SELECTED_LAWYER_STORAGE_KEY);
  } catch {
    return inMemorySelection;
  }
}

function writeSelectedLawyerId(lawyerId: string): void {
  inMemorySelection = lawyerId;
  try {
    window.localStorage.setItem(SELECTED_LAWYER_STORAGE_KEY, lawyerId);
  } catch {
    // The in-memory selection remains usable when persistence is blocked.
  }
  selectionListeners.forEach((listener) => listener());
}

function subscribeToSelectedLawyer(listener: () => void): () => void {
  selectionListeners.add(listener);
  const handleStorage = (event: StorageEvent) => {
    if (event.key === SELECTED_LAWYER_STORAGE_KEY) listener();
  };
  window.addEventListener("storage", handleStorage);
  return () => {
    selectionListeners.delete(listener);
    window.removeEventListener("storage", handleStorage);
  };
}

type Lawyer = WorkspaceSnapshot["lawyers"][number];

type Document = WorkspaceSnapshot["documents"][number];

export function resolveSelectedLawyerId(
  lawyers: Lawyer[],
  candidateId: string | null,
): string | null {
  if (candidateId && lawyers.some(({ id }) => id === candidateId)) {
    return candidateId;
  }
  return lawyers[0]?.id ?? null;
}

export function formatDocumentType(type: string): string {
  const normalized = type.trim().toLowerCase();
  if (normalized === "nda") return "NDA";
  if (normalized === "saas") return "SaaS";
  return normalized
    .split(/[-_\s]+/)
    .filter(Boolean)
    .map((word) => word[0].toUpperCase() + word.slice(1))
    .join(" ");
}

function formatUploadDate(uploadedAt: string): string {
  return new Intl.DateTimeFormat(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
    timeZoneName: "short",
  }).format(new Date(uploadedAt));
}

function WorkspaceLoading() {
  return (
    <main className="mx-auto w-full max-w-6xl px-5 py-10 sm:px-8 lg:py-16" aria-busy="true">
      <span className="sr-only">Loading workspace</span>
      <div className="h-4 w-28 animate-pulse rounded-full bg-slate-200" />
      <div className="mt-5 h-12 w-80 max-w-full animate-pulse rounded-xl bg-slate-200" />
      <div className="mt-12 grid gap-5 md:grid-cols-2 xl:grid-cols-3">
        {[0, 1, 2, 3, 4, 5].map((item) => (
          <div key={item} className="h-52 animate-pulse rounded-2xl bg-white shadow-sm ring-1 ring-slate-200" />
        ))}
      </div>
    </main>
  );
}

function InitialError({ message, retry }: { message: string; retry: () => void }) {
  return (
    <main className="mx-auto flex min-h-[70vh] w-full max-w-2xl items-center px-5 py-12 sm:px-8">
      <section className="w-full rounded-2xl bg-white p-7 shadow-sm ring-1 ring-rose-200" role="alert">
        <p className="text-sm font-semibold uppercase tracking-[0.18em] text-rose-700">Workspace unavailable</p>
        <h1 className="mt-3 text-3xl font-semibold tracking-tight text-slate-950">We couldn&apos;t load Lexroom.</h1>
        <p className="mt-3 text-slate-600">{message}</p>
        <button
          type="button"
          onClick={retry}
          className="mt-6 rounded-lg bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-slate-800 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-950"
        >
          Try again
        </button>
      </section>
    </main>
  );
}

function DocumentCard({
  document,
  uploader,
}: {
  document: Document;
  uploader: Lawyer | undefined;
}) {
  return (
    <li className="flex min-h-60 flex-col rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200">
      <div className="flex items-start justify-between gap-4">
        <span className="rounded-full bg-indigo-50 px-3 py-1 text-xs font-semibold text-indigo-700">
          {formatDocumentType(document.type)}
        </span>
        <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-amber-700">
          <span className="size-2 rounded-full bg-amber-500" aria-hidden="true" />
          Not reviewed
        </span>
      </div>
      <h3 className="mt-5 text-lg font-semibold leading-7 text-slate-950">{document.title}</h3>
      <dl className="mt-auto grid grid-cols-2 gap-x-4 gap-y-3 pt-7 text-sm">
        <div>
          <dt className="text-slate-500">Pages</dt>
          <dd className="mt-0.5 font-medium text-slate-800">{document.pages}</dd>
        </div>
        <div>
          <dt className="text-slate-500">Uploaded by</dt>
          <dd className="mt-0.5 font-medium text-slate-800">{uploader?.name ?? "Unknown lawyer"}</dd>
        </div>
        <div className="col-span-2 border-t border-slate-100 pt-3">
          <dt className="text-slate-500">Uploaded</dt>
          <dd className="mt-0.5 font-medium text-slate-800">
            <time dateTime={document.uploadedAt}>{formatUploadDate(document.uploadedAt)}</time>
          </dd>
        </div>
      </dl>
    </li>
  );
}

function NoLawyers() {
  return (
    <main className="mx-auto flex min-h-[70vh] w-full max-w-2xl items-center px-5 py-12 sm:px-8">
      <section className="w-full rounded-2xl bg-white p-7 shadow-sm ring-1 ring-amber-200" role="alert">
        <p className="text-sm font-semibold uppercase tracking-[0.18em] text-amber-700">Setup needed</p>
        <h1 className="mt-3 text-3xl font-semibold tracking-tight text-slate-950">No lawyers are available.</h1>
        <p className="mt-3 text-slate-600">Initialize the workspace data, then reload this page.</p>
      </section>
    </main>
  );
}

function WorkspaceContent() {
  const query = useQuery(WORKSPACE_QUERY_OPTIONS);
  const queryClient = useQueryClient();

  useEffect(() => {
    const refetchOnFocus = () => {
      void queryClient.refetchQueries({
        queryKey: WORKSPACE_QUERY_KEY,
        type: "active",
      });
    };
    window.addEventListener("focus", refetchOnFocus);
    return () => window.removeEventListener("focus", refetchOnFocus);
  }, [queryClient]);

  if (query.isPending) return <WorkspaceLoading />;
  if (!query.data && query.isError) {
    return <InitialError message={query.error.message} retry={() => void query.refetch()} />;
  }
  if (!query.data) return null;
  if (query.data.lawyers.length === 0) return <NoLawyers />;

  return (
    <WorkspaceReady
      snapshot={query.data}
      refreshFailed={query.isRefetchError}
      refetch={() => void query.refetch()}
    />
  );
}

function WorkspaceReady({
  snapshot,
  refreshFailed,
  refetch,
}: {
  snapshot: WorkspaceSnapshot;
  refreshFailed: boolean;
  refetch: () => void;
}) {
  const lawyers = snapshot.lawyers;
  const selectedLawyerId = useSyncExternalStore(
    subscribeToSelectedLawyer,
    readSelectedLawyerId,
    () => null,
  );
  const activeLawyerId = resolveSelectedLawyerId(lawyers, selectedLawyerId)!;
  const lawyersById = useMemo(
    () => new Map(lawyers.map((lawyer) => [lawyer.id, lawyer])),
    [lawyers],
  );

  useEffect(() => {
    if (selectedLawyerId !== activeLawyerId) {
      writeSelectedLawyerId(activeLawyerId);
    }
  }, [activeLawyerId, selectedLawyerId]);

  return (
    <main className="mx-auto w-full max-w-6xl px-5 py-10 sm:px-8 lg:py-16">
      <header className="flex flex-col gap-8 border-b border-slate-200 pb-10 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="text-sm font-semibold uppercase tracking-[0.22em] text-indigo-700">Lexroom workspace</p>
          <h1 className="mt-3 max-w-2xl text-4xl font-semibold tracking-[-0.035em] text-slate-950 sm:text-5xl">
            Contracts, ready when you are.
          </h1>
          <p className="mt-4 max-w-xl text-base leading-7 text-slate-600">
            Browse the firm&apos;s shared documents and review availability.
          </p>
        </div>
        <div className="w-full max-w-sm">
          <label htmlFor="lawyer-selector" className="mb-2 block text-sm font-semibold text-slate-800">
            Working as
          </label>
          <select
            id="lawyer-selector"
            value={activeLawyerId}
            onChange={(event) => writeSelectedLawyerId(event.target.value)}
            className="w-full rounded-xl border border-slate-300 bg-white px-4 py-3 text-sm font-medium text-slate-900 shadow-sm outline-none transition focus:border-indigo-600 focus:ring-3 focus:ring-indigo-100"
          >
            {lawyers.map((lawyer) => (
              <option key={lawyer.id} value={lawyer.id}>
                {lawyer.name} — {lawyer.title}
              </option>
            ))}
          </select>
        </div>
      </header>

      {refreshFailed && (
        <div className="mt-6 flex flex-col gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900 sm:flex-row sm:items-center sm:justify-between" role="status">
          <span>The latest refresh failed. This workspace may be out of date.</span>
          <button
            type="button"
            onClick={refetch}
            className="self-start font-semibold underline decoration-amber-400 underline-offset-4 hover:text-amber-700 sm:self-auto"
          >
            Refresh now
          </button>
        </div>
      )}

      <section className="mt-8 rounded-2xl bg-slate-950 px-6 py-6 text-white shadow-lg shadow-slate-200 sm:flex sm:items-center sm:justify-between sm:px-8">
        <div>
          <p className="text-sm font-medium text-slate-400">Monthly allowance</p>
          <p className="mt-1 text-xl font-semibold">
            {snapshot.monthlyAllowance.available} of {snapshot.monthlyAllowance.limit} reviews available this month.
          </p>
        </div>
        <p className="mt-4 text-sm font-medium text-slate-400 sm:mt-0">{snapshot.monthlyAllowance.month}</p>
      </section>

      <section className="mt-12" aria-labelledby="documents-heading">
        <div className="flex items-end justify-between gap-4">
          <div>
            <p className="text-sm font-semibold uppercase tracking-[0.18em] text-indigo-700">Shared library</p>
            <h2 id="documents-heading" className="mt-2 text-2xl font-semibold tracking-tight text-slate-950">
              Documents
            </h2>
          </div>
          <p className="text-sm text-slate-500">{snapshot.documents.length} total</p>
        </div>

        {snapshot.documents.length === 0 ? (
          <p className="mt-6 rounded-2xl border border-dashed border-slate-300 bg-white px-6 py-12 text-center text-slate-600">
            No documents available
          </p>
        ) : (
